// eslint-disable-next-line strict
import { BattleStream } from "../sim/battle-stream"
import { Dex } from '../sim/dex';
import { Cobblemon } from "../sim/cobblemon/cobblemon";

const battleMap = new Map();
const toID = Dex.toID

export function startBattle(graalShowdown: any, battleId: any, requestMessages: any) {
	const battleStream = new BattleStream();
	battleMap.set(battleId, battleStream);

	// Join messages with new line
	try {
		for (const element of requestMessages) {
			battleStream.write(element);
		}
	} catch (err: any) {
		graalShowdown.log(err.stack);
	}

	// Any battle output then gets written to the execution helper logging mechanism
	(async () => {
		for await (const output of battleStream) {
			graalShowdown.sendFromShowdown(battleId, output);
		}
	})();
}

export function sendBattleMessage(battleId: any, messages: any[]) {
	const battleStream = battleMap.get(battleId);
	messages.forEach((msg) => { battleStream.write(msg) });
}

export function getCobbledAbilityIds() {
	const base = Dex.mod(Cobblemon.modId).abilities.all()	
	const addon = Cobblemon.abilityRegistry.all();
	return JSON.stringify(base.concat(addon).map(ability => ability.id));
}

export function getCobbledItemIds() {
	return JSON.stringify(Dex.mod(Cobblemon.modId).items.all().map(item => item.id));
}

export function getCobbledMoves() {
	const base = Dex.mod(Cobblemon.modId).moves.all();
	const addon = Cobblemon.moveRegistry.all();
	return JSON.stringify(base.concat(addon));
}

export function getTypeChart() {
	return JSON.stringify(Dex.data.TypeChart);
}

export function receiveAbilityData(abilityId: any, ability: any) {
	Cobblemon.abilityRegistry.register(ability, toID(abilityId));
}

export function receiveBagItemData(itemId: any, bagItem: any) {
	Cobblemon.bagItemRegistry.register(bagItem, toID(itemId));
}

export function receiveHeldItemData(itemId: any, heldItem: any) {
	Cobblemon.heldItemRegistry.register(heldItem, toID(itemId));
}

export function receiveMoveData(moveId: any, move: any) {
	Cobblemon.moveRegistry.register(move, toID(moveId));
}

export function receiveSpeciesData(speciesArray: any[]) {
	Cobblemon.speciesRegistry.reset();
	speciesArray.forEach((speciesJson: any) => {
		const speciesData = JSON.parse(speciesJson);
		Cobblemon.speciesRegistry.register(speciesData);
	});
}

export function afterCobbledSpeciesInit() {
	Dex.modsLoaded = false;
	Dex.includeMods();
}


